import React from 'react';

import { useNavigate } from 'react-router-dom';

import { HikingBadgeOneLine } from '@apps/Hiking/@components/HikingBadge';
import { dateRangeToLocaleString, getDiffDate } from '@helpers/dateHelper';
import { formatDistance } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohLink from '@ui-kit/Link';

import { getWorkoutTypeColor } from '../@helpers/workouts.helper';
import { IWorkout } from '../@types/workouts.types';
import WorkoutTag from '../components/WorkoutTags/WorkoutTag';
import WorkoutTypeIcon from '../components/WorkoutTypeIcon';

interface IWorkoutListItemProps {
  data: IWorkout;
  name?: React.ReactNode;
  last?: React.ReactNode;
}

const WorkoutListItem: React.FC<IWorkoutListItemProps> = ({ data, name, last }) => {
  const navigate = useNavigate();
  return (
    <PohRow className="my-n1 align-items-center">
      <PohCol lg={1} md={3} sm={4} xs={4} className="text-sm-end">
        <div className="d-flex align-items-center">
          <PohAva
            src={data.photos?.[0]?.url_preview}
            alt={data.type.name}
            icon={<WorkoutTypeIcon type={data.type} style={{ fill: 'none', height: '80%' }} />}
            className="me-2"
            color={getWorkoutTypeColor(data.type.id)}
            style={{
              color: getWorkoutTypeColor(data.type.id),
              backgroundColor: `color-mix(in srgb, ${getWorkoutTypeColor(data.type.id)}, white 90%)`,
            }}
          />
          &nbsp;
          {data.type.name}
        </div>
      </PohCol>
      <PohCol
        lg={1}
        md={2}
        sm={4}
        xs={4}
        className="d-flex justify-content-between align-items-center"
      >
        <PohBadge variant={BadgeVariant.Light}>{formatDistance(data.distance)}</PohBadge>
      </PohCol>
      <PohCol
        lg={1}
        md={2}
        sm={4}
        xs={4}
        className="d-flex justify-content-between align-items-center"
      >
        <small title="km/h" className="text-success">
          {round(data.speed_avg / 10, 1)}
        </small>
        <small>{getDiffDate(data.date_start, data.date_finish).toLocaleTimeString()}</small>
      </PohCol>

      <PohCol lg={3} md={5} sm={12} xs={12} className="text-truncate">
        {name ? name : <small>{data.name}</small>}
      </PohCol>
      <PohCol lg={2} md={4} sm={6} xs={12}>
        <small>
          <small>{dateRangeToLocaleString(data.date_start, data.date_finish)}</small>
        </small>
      </PohCol>
      <PohCol lg={2} md={4} sm={6} xs={6} className="d-flex justify-content-between">
        {data.hiking?.id && (
          <PohLink
            className="d-inline-block text-truncate"
            onClick={(e) => e.stopPropagation()}
            href={`/hiking/${data.hiking.id}`}
          >
            <HikingBadgeOneLine hiking={data.hiking} />
          </PohLink>
        )}
        {data.tags.map((x) => (
          <WorkoutTag
            tag={x}
            key={x.id}
            onClick={(e) => {
              e.stopPropagation();
              const curSearch = new URLSearchParams(location.search);
              curSearch.set('tag', x.id.toString());
              navigate(`?${curSearch}`);
            }}
          />
        ))}
      </PohCol>
      <PohCol lg={2} md={4} sm={12} xs={12} className="text-end">
        {last ? (
          last
        ) : (
          <PohAva
            src={data.user.photo}
            title={[data.user.name, new Date(data.date_upload).toLocaleString()].join(' ')}
          />
        )}
      </PohCol>
    </PohRow>
  );
};

export default WorkoutListItem;
